    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = -4 + (-2) = -6</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = -3</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 4 + (-1) = 3</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها <span dir=\"ltr\" class=\"expr\">(-3</span> ; <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 1 + 1 = 2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = 1</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 4 + 0 = 4</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = 2</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها (1 ; 2)"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 2 + 5 = 7</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 3 + 6 = 9</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها <span dir=\"ltr\" class=\"expr\">(<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span></span> ; <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 4 + (-3) = 1</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 0 + (-6) = -6</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = -3</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها <span dir=\"ltr\" class=\"expr\">(<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span> ; <span dir=\"ltr\" class=\"expr\">-3)</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 6 + (-2) = 4</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = 2</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = -1 + 3 = 2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = 1</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها (2 ; 1)"}],
