    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 1 + (-3) = -2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = -1</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = -2 + (-6) = -8</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = -4</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها <span dir=\"ltr\" class=\"expr\">(-1</span> ; <span dir=\"ltr\" class=\"expr\">-4)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = -5 + 1 = -4</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = -2</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 2 + 3 = 5</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها <span dir=\"ltr\" class=\"expr\">(-2</span> ; <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 3 + (-1) = 2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = 1</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 0 + 2 = 2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = 1</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها (1 ; 1)"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = -2 + 2 = 0</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = 0</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 6 + (-4) = 2</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = 1</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها (0 ; 1)"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"القاعدة","math":"إحداثيات منتصف [AB] هما <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">xA + xB</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">yA + yB</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xA + xB = 3 + 3 = 6</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">xM = 3</span>"},{"quoi":"نجمع الترتيبتين","math":"<span dir=\"ltr\" class=\"expr\">yA + yB = 4 + 6 = 10</span>"},{"quoi":"نقسم على 2","math":"<span dir=\"ltr\" class=\"expr\">yM = 5</span>"},{"quoi":"النتيجة","math":"النقطة M إحداثياتها (3 ; 5)"}],
